<div class="page-head"><div><h1>{{ $group->name ?: '移行 #'.$group->id }}</h1><p class="muted">{{ $group->purpose ?: '目的未設定' }} · {{ ['planned'=>'予定','processing'=>'処理中','completed'=>'完了','cancelled'=>'取消','error'=>'エラー'][$group->status] ?? $group->status }}</p></div>@if(!in_array($group->status, ['completed','cancelled','error']))<a class="button secondary" href="{{ route('transfers.steps.create', $group) }}">ステップを追加</a>@endif</div>
